package com.brightloop.invoice;
import com.brightloop.catalog.Customer;import com.brightloop.subscription.Subscription;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.time.LocalDate;import java.util.ArrayList;import java.util.List;
@Entity @Table(name="invoices") public class Invoice{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(name="invoice_number",nullable=false,unique=true,length=40) String invoiceNumber;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="customer_id",nullable=false) Customer customer;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subscription_id") Subscription subscription;@Column(name="quotation_id") Long quotationId;@Column(name="billing_period_start") LocalDate billingPeriodStart;@Column(name="billing_period_end") LocalDate billingPeriodEnd;@Column(name="issue_date",nullable=false) LocalDate issueDate;@Column(name="due_date",nullable=false) LocalDate dueDate;@Column(nullable=false,length=20) String status="CONFIRMED";@Column(nullable=false,precision=14,scale=2) BigDecimal subtotal;@Column(name="tax_amount",nullable=false,precision=14,scale=2) BigDecimal taxAmount;@Column(name="discount_amount",nullable=false,precision=14,scale=2) BigDecimal discountAmount;@Column(nullable=false,precision=14,scale=2) BigDecimal total;@Column(name="amount_paid",nullable=false,precision=14,scale=2) BigDecimal amountPaid=BigDecimal.ZERO;@Column(nullable=false,precision=14,scale=2) BigDecimal outstanding;@Column(name="created_at",nullable=false,updatable=false) Instant createdAt=Instant.now();@OneToMany(mappedBy="invoice",cascade=CascadeType.ALL,orphanRemoval=true) List<InvoiceLine> lines=new ArrayList<>();
 protected Invoice(){}public Invoice(String number,Customer customer,Subscription subscription,Long quote,LocalDate periodStart,LocalDate periodEnd,LocalDate issue,LocalDate due,BigDecimal subtotal,BigDecimal tax,BigDecimal discount,BigDecimal total){this.invoiceNumber=number;this.customer=customer;this.subscription=subscription;this.quotationId=quote;this.billingPeriodStart=periodStart;this.billingPeriodEnd=periodEnd;this.issueDate=issue;this.dueDate=due;this.subtotal=subtotal;this.taxAmount=tax;this.discountAmount=discount;this.total=total;this.outstanding=total;this.status="CONFIRMED";}
 public void addLine(InvoiceLine line){lines.add(line);}public void applyPayment(BigDecimal amount){amountPaid=amountPaid.add(amount);outstanding=total.subtract(amountPaid);status=outstanding.signum()==0?"PAID":"PARTIALLY_PAID";}public void cancel(){if(!"CONFIRMED".equals(status)||amountPaid.signum()>0)throw new IllegalStateException("Only unpaid confirmed invoices can be cancelled");status="CANCELLED";outstanding=BigDecimal.ZERO;}public Long getId(){return id;}public String getInvoiceNumber(){return invoiceNumber;}public Customer getCustomer(){return customer;}public Subscription getSubscription(){return subscription;}public LocalDate getBillingPeriodStart(){return billingPeriodStart;}public LocalDate getBillingPeriodEnd(){return billingPeriodEnd;}public LocalDate getIssueDate(){return issueDate;}public LocalDate getDueDate(){return dueDate;}public String getStatus(){return status;}public BigDecimal getSubtotal(){return subtotal;}public BigDecimal getTaxAmount(){return taxAmount;}public BigDecimal getDiscountAmount(){return discountAmount;}public BigDecimal getTotal(){return total;}public BigDecimal getAmountPaid(){return amountPaid;}public BigDecimal getOutstanding(){return outstanding;}public List<InvoiceLine> getLines(){return lines;}
}
